import { useState } from "react";
import { Card, CardContent } from "./ui/card";
import { Input } from "./ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./ui/select";
import { Button } from "./ui/button";
interface Cliente {
  id: number;
  nome: string;
  whatsapp: string;
  plano: string;
}

export default function PainelClientesIA() {
  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [nome, setNome] = useState<string>("");
  const [whatsapp, setWhatsapp] = useState<string>("");
  const [plano, setPlano] = useState<string>("basico");

  const adicionarCliente = () => {
    const novoCliente: Cliente = {
      id: Date.now(),
      nome,
      whatsapp,
      plano,
    };
    setClientes([...clientes, novoCliente]);
    setNome("");
    setWhatsapp("");
    setPlano("basico");
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">Painel de Clientes - Agente IA</h1>

      <Card className="mb-6">
        <CardContent className="space-y-4 pt-4">
          <Input
            placeholder="Nome do cliente"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
          />
          <Input
            placeholder="Número WhatsApp (com DDD)"
            value={whatsapp}
            onChange={(e) => setWhatsapp(e.target.value)}
          />
          <Select value={plano} onValueChange={setPlano}>
            <SelectTrigger>
              <SelectValue placeholder="Selecione um plano" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="basico">Básico (R$ 49)</SelectItem>
              <SelectItem value="intermediario">Intermediário (R$ 99)</SelectItem>
              <SelectItem value="avancado">Avançado (R$ 149)</SelectItem>
            </SelectContent>
          </Select>
          <Button onClick={adicionarCliente}>Adicionar Cliente</Button>
        </CardContent>
      </Card>

      <div className="grid gap-4">
        {clientes.map((cliente) => (
          <Card key={cliente.id}>
            <CardContent className="pt-4">
              <p><strong>Nome:</strong> {cliente.nome}</p>
              <p><strong>WhatsApp:</strong> {cliente.whatsapp}</p>
              <p><strong>Plano:</strong> {cliente.plano}</p>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}
